def read(name):return json.loads((p/name).read_text(encoding='utf-8-sig'))
def ref(name):return {'path':name,'sha256':hashlib.sha256((p/name).read_bytes()).hexdigest()}
def write(name,data):
 (p/name).write_text(data if isinstance(data,str) else json.dumps(data,ensure_ascii=False,indent=2),encoding='utf8')
