claim('feature-overview','fact','Developer describes feeding/collecting, upgrades, Colony Points, workers and reset rewards.',['itch','steam'],'Official feature headings/paragraphs from Feed the worms through Start again. Grow stronger. Website attributes the overview; no exact table/completeness/playtest inference.')
claim('source-date','date','Codex read the official listings on 8 October 2026 UTC.',['source-date'],'Capture checkedAt=2026-10-08; current date is not automatically substituted into metadata.')
claim('authorship','fact','Independent AI-assisted site under Hlele, with lianlele168@gmail.com corrections contact and no affiliation.',['implementation'],'Workspace identity plus archived existing contact; separate agent review scope. No fabricated human experience.')
claim('review-scope','verification','Codex reviewed official sources and the local site layout, content, interactions and arithmetic, without claiming game play.',['implementation','interactions'],'Actual source captures, six-route screenshots, 17-case Chrome test report and four calibration observations. Parent review remains separate.')
claim('editorial-routine','fact','Observation routine is editorial advice, not game achievements or fastest-route testing.',['implementation'],'Read walkthrough text: one changed condition, exact displayed descriptions, version notes, unknowns left unknown. Suggestions have no claimed numeric effect.')
claim('worksheet-formula','formula','Net rate=(ending-starting)/minutes; receipts=(ending-starting+spending)/minutes; comparison=run2 net-run1 net.',['implementation','interactions'],'Accounting identity end=start+receipts-spending under disclosed inputs; implementation read and browser outputs independently compared to hand-computed synthetic examples.')
claims[-1].update({'method':'Reconstruct receipts by adding recorded spending to balance change, divide each by elapsed minutes, then subtract first net rate from second. JavaScript finite range checked; display rounds to at most 2 decimal places. This is user-entered interval accounting, not a game mechanism.','units':'Balances/spending: same game balance unit; elapsed time: minutes; outputs: those units per minute. Not real-world currency.','assumptions':'All spending recorded; same units and comparable version/conditions; exclude resets, refunds, transfers, one-off rewards and unrecorded purchases. Observed comparison is not causality or a future prediction.','calibration':tests['calibrations'],'calibrationArtifact':ref('quality/artifacts/interaction-review.json')})
claim('worked-example','number','Synthetic example 100→160 with 20 spent over 2 min yields net30/receipts40; 100→140 with 0 spent over 2 min yields20, difference-10.',['interactions'],'Current Chrome input values and visible outputs in calibration records; publicly labeled invented worksheet inputs, not game results.')
claim('worksheet-validation','fact','Blank, invalid, inconsistent or overflow values show an explanation; inputs clear on reload and can be cleared manually.',['implementation','interactions'],'Tests 1–7 and component measure(); no fabricated defaults, rates or saved state.')
claim('checklist','number','Five editorial observation checks can be toggled, filtered, reset, persisted locally and copied; progress percentage counts these checks.',['implementation','interactions'],'Actual five task data entries, UI 0/5–5/5 and count-derived ring; tests cover reload, filter/empty, all/reset, copy, corrupt/denied storage. Not game progress.')
claim('privacy','fact','Checklist IDs stored locally; worksheet page state; app sends neither to a server; no auth/ads/analytics or game embed in this build.',['implementation','interactions'],'Read application imports/components and current export; no external browser requests in collector. Hosting/external-link limitations are disclosed.')
